#!/usr/bin/env python3
"""
Test that AW Adapter generated events validate against contract schemas.
"""

import json
import os
import sys
import tempfile
import uuid
from datetime import datetime, timezone
from pathlib import Path

sys.path.insert(0, str(os.path.dirname(__file__)))
sys.path.insert(0, str(Path(__file__).parent.parent / "tests"))

from pathlib import Path
from main import (
    EventTransformer,
    PrivacyFilter,
    Config,
)

from test_schemas import SchemaTester


def test_generated_events_validate():
    """Test that events generated by AW Adapter validate against schemas."""
    import yaml

    with tempfile.NamedTemporaryFile(mode="w", suffix=".yaml", delete=False) as f:
        yaml.dump({
            "aw_server_url": "http://localhost:5600",
            "poll_interval_seconds": 5,
            "instance_id": str(uuid.uuid4()),
            "privacy": {"enabled": True},
        }, f)
        config_path = f.name

    try:
        config = Config(config_path)
        pf = PrivacyFilter(config.data.get("privacy", {}))
        transformer = EventTransformer(config, pf, config.data["instance_id"])

        # Load schemas
        tester = SchemaTester()
        tester.load_schemas()

        base_ts = datetime.now(timezone.utc).timestamp()

        # Test window.focus.changed event
        raw_window = {
            "id": 1,
            "timestamp": base_ts,
            "duration": 1.0,
            "data": {
                "app": "Revit.exe",
                "title": "Project_A.rvt - Autodesk Revit 2025",
                "pid": 8842,
                "exe_path": "C:\\Program Files\\Autodesk\\Revit 2025\\Revit.exe",
            },
        }

        event = transformer.transform_window_event(raw_window)
        assert event is not None, "Window event transformation failed"

        print(f"Generated window event: {json.dumps(event, indent=2)}")

        # Validate against schema
        schema = tester.get_schema_for_event(event)
        valid, msg = tester.validate_event(event, schema)
        assert valid, f"Window event validation failed: {msg}"
        print("PASS: window.focus.changed event validates against schema")

        # Test afk.state.changed event
        raw_afk = {
            "id": 2,
            "timestamp": base_ts + 10,
            "duration": 0,
            "data": {
                "status": "afk",
                "idle_duration": 300,
            },
        }

        event = transformer.transform_afk_event(raw_afk)
        assert event is not None, "AFK event transformation failed"

        print(f"Generated AFK event: {json.dumps(event, indent=2)}")

        # Validate against schema
        schema = tester.get_schema_for_event(event)
        valid, msg = tester.validate_event(event, schema)
        assert valid, f"AFK event validation failed: {msg}"
        print("PASS: afk.state.changed event validates against schema")

        # Test with privacy filter enabled - window title should be hashed
        raw_window_private = {
            "id": 3,
            "timestamp": base_ts + 20,
            "duration": 1.0,
            "data": {
                "app": "chrome.exe",
                "title": "My Secret Password Page - Google Chrome",
                "pid": 1234,
                "exe_path": "C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe",
            },
        }

        event = transformer.transform_window_event(raw_window_private)
        assert event is not None

        # Check privacy filter applied
        current_title = event["payload"]["current"]["window_title"]
        assert current_title.startswith("[HASH:") or current_title == "[REDACTED]", \
            f"Privacy filter not applied: {current_title}"
        print(f"PASS: Privacy filter applied to window title: {current_title}")

        print("\nALL TESTS All schema validation tests passed!")

    finally:
        os.unlink(config_path)


if __name__ == "__main__":
    test_generated_events_validate()